def pre_suggestion_index_source(source):
    from suggestion_anchor_owner_scope_contract import pre_suggestion_anchor_owner
    source = pre_suggestion_anchor_owner(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_suggestion_index_source_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_index_source(data.decode()).encode() if path.suffix == '.swift' else data

